-	(VEOF VEOL VERASE VINTR VKILL VQUIT
-	VSUSP VSTART VSTOP VMIN VTIME NCCS);
+	(VEOF, VEOL, VERASE, VINTR, VKILL, VQUIT,
+	VSUSP, VSTART, VSTOP, VMIN, VTIME);

 use vars qw(
     $VERSION @ISA @EXPORT @EXPORT_OK
@@ -19,7 +19,7 @@
 @EXPORT = qw(
 	read_password 
 );
-$VERSION = '0.07';
+$VERSION = '0.08';

 # The special characters in the input stream
 %SPECIAL = (
